const parts = msg.topic.split('/');
const deviceId = parts[1];
let b = msg.payload;
if (Buffer.isBuffer(b)) b = b.toString();
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
if (typeof b !== 'object' || !b) b = {};

msg.deviceId = deviceId;
msg.alarmType = b.type || 'evento';
msg.camName = b.name || '';   // qual camera disparou
msg.params = [deviceId];

// eventos que nao merecem push (ficam so no historico)
const mudos = ['snapshot_taken', 'recordings_cleared'];
if (mudos.indexOf(msg.alarmType) >= 0) return null;
return msg;

const rows = msg.payload || [];
const tokens = rows.map(r => r.fcm_token).filter(Boolean);
if (tokens.length === 0) return null;

const dev = (rows[0] && rows[0].device_name) || msg.deviceId;
const cam = msg.camName || '';
const onde = cam ? cam + ' \u00b7 ' + dev : dev;

let title, body;
switch (msg.alarmType) {
    case 'movimento':
        title = 'Movimento detectado';
        body = onde;
        break;
    case 'tvbox_offline':
        title = 'Equipamento fora do ar';
        body = dev + ' parou de responder';
        break;
    case 'camera_offline':
        title = 'C\u00e2mera desconectada';
        body = onde;
        break;
    case 'camera_online':
        title = 'C\u00e2mera reconectada';
        body = onde;
        break;
    default:
        title = 'Alarme';
        body = dev + ': ' + msg.alarmType;
}

msg.headers = { 'Content-Type': 'application/json' };
msg.payload = JSON.stringify({ tokens: tokens, title: title, body: body });
return msg;
